 Object.freeze({minute:10,id:'isb-first-landing',summary:'A primeira nave de transporte ISB desembarca agentes e soldados de assalto.'}),
 Object.freeze({minute:15,id:'second-tie-patrol',summary:'Uma segunda patrulha TIE chega à região.'}),
 Object.freeze({minute:25,id:'system-patrol-craft',summary:'Naves de patrulha do sistema assumem posições de interceptação.'}),
 Object.freeze({minute:30,id:'imperial-reinforcements',summary:'Reforços imperiais adicionais chegam e as defesas da IsoTech começam a ceder.'})
