 if(typeof actionId!=='string'||! /^[A-Za-z0-9][A-Za-z0-9:._-]{0,99}$/.test(actionId)||['__proto__','prototype','constructor'].includes(actionId))throw Error('Identificador de ação imperial inválido.');
