export function markBeyondTheRimRewardsApplied(world,details={}){const next=clone(world);next.publishedAdventureRewards={...(next.publishedAdventureRewards||{}),[ID]:{applied:true,appliedAt:now(),credits:Number(details.credits)||0,note:details.note||null}};if(next?.publishedAdventure?.id===ID)next.publishedAdventure.rewardsApplied=true;return next}
